From 4f3842bcb60c064d8b224964081503eb84374ecb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:08:00 +0100
Subject: [PATCH 1/2] applets/batterymonitor: collapse duplicate inhibitions

An app that keeps requesting the same inhibition without releasing it
got one popup entry per request, and the list was rebuilt on every
change, so a few hundred of them kept plasmashell busy. Keep only one.

BUG: 526663
---
 .../batterymonitor/plugin/inhibitioncontrol.cpp    | 14 ++++++++++++++
 1 file changed, 14 insertions(+)

diff --git a/applets/batterymonitor/plugin/inhibitioncontrol.cpp b/applets/batterymonitor/plugin/inhibitioncontrol.cpp
index 4adbe9670..34bc5bc2d 100644
--- a/applets/batterymonitor/plugin/inhibitioncontrol.cpp
+++ b/applets/batterymonitor/plugin/inhibitioncontrol.cpp
@@ -17,6 +17,7 @@
 #include <QDBusReply>
 #include <QDBusServiceWatcher>
 #include <QDBusVariant>
+#include <QSet>
 #include <QString>
 #include <QVariant>

@@ -322,6 +323,7 @@ void InhibitionControl::checkInhibitions()
 QList<RequestedInhibition> InhibitionControl::updatedInhibitions(const QList<PolicyAgentInhibition> &inhibitions)
 {
     QList<RequestedInhibition> result;
+    QSet<QString> seen;

     for (const PolicyAgentInhibition &inhibition : inhibitions) {
         if (inhibition.who == "plasmashell"_L1 || inhibition.who == "org.kde.plasmashell"_L1) {
@@ -335,6 +337,18 @@ QList<RequestedInhibition> InhibitionControl::updatedInhibitions(const QList<Pol
             continue; // maybe we'll support other inhibition types at a later point
         }

+        // An application may hold any number of inhibitions at the same time, and a buggy
+        // one can keep requesting them without ever releasing. Such duplicates are
+        // indistinguishable in the UI, so only keep the first of each kind: the Repeater in
+        // InhibitionItem.qml instantiates one delegate per entry and discards all of them
+        // whenever the list changes, which stalls plasmashell for good once an application
+        // has leaked a few hundred inhibitions.
+        const QString key = inhibition.who + u'\x1f' + inhibition.why + u'\x1f' + inhibition.what + u'\x1f' + QString::number(inhibition.flags);
+        if (seen.contains(key)) {
+            continue;
+        }
+        seen.insert(key);
+
         QString prettyName;
         QString icon;
         m_data.populateApplicationData(inhibition.who, &prettyName, &icon);
-- 
