From 789284aef01da1507cd6383e3665eddb2a952461 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:15:24 +0100
Subject: [PATCH 2/2] applets/batterymonitor: keep one inhibition list request
 in flight

Every inhibition change made the applet fetch the whole list again, so
blocking or adding hundreds at once sent as many large requests, which
clogged plasmashell's D-Bus connection for good. Coalesce the requests.

BUG: 526663
---
 .../batterymonitor/plugin/inhibitioncontrol.cpp   | 15 +++++++++++++++
 applets/batterymonitor/plugin/inhibitioncontrol.h |  2 ++
 2 files changed, 17 insertions(+)

diff --git a/applets/batterymonitor/plugin/inhibitioncontrol.cpp b/applets/batterymonitor/plugin/inhibitioncontrol.cpp
index 34bc5bc2d..1ed787861 100644
--- a/applets/batterymonitor/plugin/inhibitioncontrol.cpp
+++ b/applets/batterymonitor/plugin/inhibitioncontrol.cpp
@@ -23,6 +23,8 @@

 #include <KService>

+#include <utility>
+
 #include "inhibitmonitor_p.h"

 using namespace Qt::Literals::StringLiterals;
@@ -301,6 +303,14 @@ void InhibitionControl::onPolicyAgentPropertiesChanged(const QString &ifaceName,

 void InhibitionControl::checkInhibitions()
 {
+    // Many inhibitions can change at once, e.g. when an app releases all of them,
+    // so keep a single call in flight instead of one per change notification
+    if (m_inhibitionsCallPending) {
+        m_inhibitionsChangedMeanwhile = true;
+        return;
+    }
+    m_inhibitionsCallPending = true;
+
     QDBusMessage msg = QDBusMessage::createMethodCall(SOLID_POWERMANAGEMENT_SERVICE, POLICY_AGENT_PATH, u"org.freedesktop.DBus.Properties"_s, u"Get"_s);
     msg << POLICY_AGENT_IFACE << u"RequestedInhibitions"_s;
     QDBusPendingCall call = QDBusConnection::sessionBus().asyncCall(msg);
@@ -317,6 +327,11 @@ void InhibitionControl::checkInhibitions()
             qCWarning(APPLETS::BATTERYMONITOR) << "Failed to retrieve inhibitions:" << reply.error().message();
         }
         watcher->deleteLater();
+
+        m_inhibitionsCallPending = false;
+        if (std::exchange(m_inhibitionsChangedMeanwhile, false)) {
+            checkInhibitions();
+        }
     });
 }

diff --git a/applets/batterymonitor/plugin/inhibitioncontrol.h b/applets/batterymonitor/plugin/inhibitioncontrol.h
index c9fc1dacd..4ce048f0e 100644
--- a/applets/batterymonitor/plugin/inhibitioncontrol.h
+++ b/applets/batterymonitor/plugin/inhibitioncontrol.h
@@ -122,6 +122,8 @@ private:
     std::unique_ptr<QDBusServiceWatcher> m_solidWatcher;
     std::unique_ptr<QDBusServiceWatcher> m_fdoWatcher;
     bool m_isSilent = false;
+    bool m_inhibitionsCallPending = false;
+    bool m_inhibitionsChangedMeanwhile = false;

     ApplicationData m_data;
 };
-- 
